-- TEST ONLY. Fixed synthetic identities and SQL claims; no real Auth login.
-- One transaction always rolled back: no persistent account/role, no endpoint,
-- no external network call and no existing reservation/payment changed.
begin;
set local statement_timeout='120s';
set local lock_timeout='5s';
select set_config('qa.delegation_ids',(select jsonb_object_agg(label,gen_random_uuid())::text from unnest(array['root','head_a','head_b','agent_a','agent_b','agent_c','finance_head','finance_agent','support_head','support_agent','client','provider'])label),true);
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data)
select value::uuid,'qa-delegation-rollback-'||value||'@example.invalid',now(),'{"qa_suppress_email":true}',jsonb_build_object('display_name','QA delegation rollback '||key,'legal_accepted','true')from jsonb_each_text(current_setting('qa.delegation_ids')::jsonb);
update public.profiles set role='admin'where id=(current_setting('qa.delegation_ids')::jsonb->>'root')::uuid;
insert into public.admin_user_roles(user_id,role_id,requires_mfa)select(current_setting('qa.delegation_ids')::jsonb->>'root')::uuid,id,true from public.admin_roles where key='super_admin';
insert into public.provider_profiles(profile_id,business_name,slug,city,onboarding_progress)
values((current_setting('qa.delegation_ids')::jsonb->>'provider')::uuid,'QA delegation rollback provider','qa-delegation-'||(current_setting('qa.delegation_ids')::jsonb->>'provider'),'Dakar',100);
insert into public.professional_onboarding(provider_id,status)values((current_setting('qa.delegation_ids')::jsonb->>'provider')::uuid,'submitted');
with inserted as(insert into public.support_tickets(requester_id,subject)values((current_setting('qa.delegation_ids')::jsonb->>'client')::uuid,'QA delegation rollback claim')returning id)select set_config('qa.delegation_ticket',id::text,true)from inserted;
set local role authenticated;
do $$declare ids jsonb:=current_setting('qa.delegation_ids')::jsonb;ta uuid;tb uuid;tf uuid;ts uuid;l uuid;c uuid;fc uuid;sc uuid;inv uuid;actor uuid;denied_permission text;v integer;
begin
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids->>'root','role','authenticated','aal','aal1')::text,true);
 begin perform public.department_set_team(null,null,'commercial','QA delegation rollback A','qa-delegation-rollback-'||(ids->>'head_a')||'@example.invalid',true,'Recette transactionnelle');raise exception 'AAL1 appointed head';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids->>'root','role','authenticated','aal','aal2')::text,true);
 ta:=public.department_set_team(null,null,'commercial','QA delegation rollback A','qa-delegation-rollback-'||(ids->>'head_a')||'@example.invalid',true,'Recette transactionnelle');
 tb:=public.department_set_team(null,null,'commercial','QA delegation rollback B','qa-delegation-rollback-'||(ids->>'head_b')||'@example.invalid',true,'Recette transactionnelle');
 tf:=public.department_set_team(null,null,'finance','QA delegation rollback Finance','qa-delegation-rollback-'||(ids->>'finance_head')||'@example.invalid',true,'Recette transactionnelle');
 ts:=public.department_set_team(null,null,'support','QA delegation rollback Support','qa-delegation-rollback-'||(ids->>'support_head')||'@example.invalid',true,'Recette transactionnelle');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids->>'head_a','role','authenticated','aal','aal2')::text,true);
 if public.department_can_manage(tb)then raise exception 'Foreign team administration';end if;
 begin perform public.admin_assign_role((ids->>'agent_a')::uuid,'super_admin','Forbidden escalation');raise exception 'Manager granted Super Admin';exception when insufficient_privilege then null;end;
 perform public.department_add_member(ta,'qa-delegation-rollback-'||(ids->>'agent_a')||'@example.invalid','Recrutement de recette');
 perform public.department_add_member(ta,'qa-delegation-rollback-'||(ids->>'agent_c')||'@example.invalid','Recrutement de recette');
 c:=public.department_save_case(null,null,ta,(ids->>'agent_a')::uuid,'QA dossier','Instructions',null,(ids->>'provider')::uuid,null,null);
 inv:=public.department_prepare_invitation(ta,'qa-invitation-'||gen_random_uuid()::text||'@example.invalid','Agent','Recette');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids->>'agent_a','role','authenticated','aal','aal2')::text,true);
 insert into public.crm_leads(name,team_id,linked_provider_id)values('QA delegation rollback prospect',ta,(ids->>'provider')::uuid)returning id into l;
 insert into public.crm_activities(lead_id,kind,body)values(l,'visit','Visite déclarée de recette');
 begin perform public.department_add_member(ta,'qa-delegation-rollback-'||(ids->>'agent_b')||'@example.invalid','Forbidden recruitment');raise exception 'Worker recruited';exception when insufficient_privilege then null;end;
 begin perform public.review_professional_application((ids->>'provider')::uuid,'approved','Quatre pièces manquantes');raise exception 'Incomplete dossier approved';exception when raise_exception then if sqlerrm not like 'Dossier incomplet%'then raise;end if;end;
 begin perform public.activate_internal_invitation((ids->>'agent_a')::uuid);raise exception 'Client-side activation';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids->>'head_b','role','authenticated','aal','aal2')::text,true);
 perform public.department_add_member(tb,'qa-delegation-rollback-'||(ids->>'agent_b')||'@example.invalid','Recrutement de recette');
 if exists(select 1 from public.crm_leads where id=l)or exists(select 1 from public.crm_activities where lead_id=l)then raise exception 'Cross-team CRM disclosure';end if;
 begin perform public.department_case_detail(c);raise exception 'Cross-team case disclosure';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids->>'head_a','role','authenticated','aal','aal2')::text,true);
 if(select sum((a->>'visits')::int)from jsonb_array_elements(public.department_team_report(ta)->'agents')a)<>1 then raise exception 'Visit report incorrect';end if;
 perform public.department_move_prospect(l,1,(ids->>'agent_c')::uuid,ta);
 perform public.department_save_case(c,1,ta,(ids->>'agent_c')::uuid,'QA réaffectation','Instructions',null,(ids->>'provider')::uuid,null,null);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids->>'agent_a','role','authenticated','aal','aal2')::text,true);
 if exists(select 1 from public.crm_leads where id=l)or public.department_provider_access((ids->>'provider')::uuid)then raise exception 'Former assignee retained access';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids->>'agent_c','role','authenticated','aal','aal2')::text,true);
 if not exists(select 1 from public.crm_leads where id=l)then raise exception 'New assignee missing prospect';end if;
 perform public.department_update_case(c,2,'in_progress','Prise en charge');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids->>'finance_head','role','authenticated','aal','aal2')::text,true);
 perform public.department_add_member(tf,'qa-delegation-rollback-'||(ids->>'finance_agent')||'@example.invalid','Recrutement de recette');
 fc:=public.department_save_case(null,null,tf,(ids->>'finance_agent')::uuid,'QA finance','Contrôle sans mouvement financier',null,null,null,null);
 if not public.has_admin_permission('payments.read')or public.has_admin_permission('payouts.manage')then raise exception 'Finance head permission mismatch';end if;
 perform public.finance_payment_overview();
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids->>'finance_agent','role','authenticated','aal','aal2')::text,true);
 foreach denied_permission in array array['payments.read','payments.refund','payouts.manage','payouts.read','teams.manage']loop if public.has_admin_permission(denied_permission)then raise exception 'Finance agent leaked permission %',denied_permission;end if;end loop;
 perform public.department_case_detail(fc);perform public.department_update_case(fc,1,'completed','Contrôle de recette terminé');
 begin perform public.finance_payment_overview();raise exception 'Finance agent global overview';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids->>'support_head','role','authenticated','aal','aal2')::text,true);
 perform public.department_add_member(ts,'qa-delegation-rollback-'||(ids->>'support_agent')||'@example.invalid','Recrutement de recette');
 sc:=public.department_save_case(null,null,ts,(ids->>'support_agent')::uuid,'QA réclamation','Répondre au demandeur',null,null,null,current_setting('qa.delegation_ticket')::uuid);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids->>'support_agent','role','authenticated','aal','aal2')::text,true);
 perform public.department_reply_case(sc,'Réponse publique de recette',false);perform public.department_reply_case(sc,'Note privée de recette',true);
 perform public.department_update_case(sc,1,'completed','Réclamation résolue');
 if public.has_admin_permission('support.manage')or public.has_admin_permission('payments.read')then raise exception 'Support worker broad permission';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids->>'client','role','authenticated','aal','aal1')::text,true);
 if(select count(*)from public.support_messages where ticket_id=current_setting('qa.delegation_ticket')::uuid)<>1 then raise exception 'Client internal note disclosure or missing public reply';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids->>'root','role','authenticated','aal','aal2')::text,true);
 perform public.department_set_team(ta,1,'commercial','QA delegation rollback A','qa-delegation-rollback-'||(ids->>'head_b')||'@example.invalid',true,'Remplacement de recette');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids->>'head_a','role','authenticated','aal','aal2')::text,true);
 if public.department_can_manage(ta)then raise exception 'Former head retained access';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids->>'head_b','role','authenticated','aal','aal2')::text,true);
 perform public.department_member_action(ta,(ids->>'agent_c')::uuid,'revoke','Fin de recette');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids->>'agent_c','role','authenticated','aal','aal2')::text,true);
 if exists(select 1 from public.crm_leads where id=l)or exists(select 1 from public.department_cases where id=c)then raise exception 'Revocation did not remove access';end if;
end $$;
reset role;
rollback;
select 'PASS hosted PostgreSQL delegation: MFA claims, teams, CRM, KYC, finance, support, replacement/revocation; all synthetic data rolled back. Real Auth login not tested.'result;
